.shell-header { height: 44px; background: var(--bg-elevated); color: var(--text-primary); border-bottom: 1px solid var(--border-subtle); box-shadow: var(--shadow-sm); display: flex; align-items: center; padding: 0 16px; gap: 12px; }
.shell-header .product { font-weight: 600; }
